#[test]
fn sqlite_snapshot_docx_exact_aggregate_row_budget(){let snapshot=fixture();let defaults=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let count=db.tables.iter().map(|table|table.rows.len()).sum::<usize>();let exact=SqliteDatabaseLimits{max_rows:count,..defaults};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).is_ok());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:count-1,..defaults})).is_err());}

#[test]
fn sqlite_snapshot_docx_rejects_dangling_and_shared_package_owners(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for(table,row,column,value)in[("docx_document",0,2,SqliteValue::Integer(2)),("docx_xml_part",1,4,SqliteValue::Integer(1)),("docx_relationship",0,1,SqliteValue::Integer(99)),("docx_default_content_type",0,2,SqliteValue::Integer(99)),("docx_relationship_owner",1,2,SqliteValue::Text("".into()))]{let mut invalid=db.clone();invalid.table_mut(table).unwrap().rows[row].values[column]=value;assert!(DocxSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"{table}");}}
#[test]
fn sqlite_snapshot_docx_literal_large_part_bytes_have_interior_controls(){let mut snapshot=fixture();snapshot.opc.parts[0].bytes=vec![0x97;100000];let limits=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut observed=false;let mut callback=|event:SqliteSnapshotProgress|{if event.phase==phase&&event.total==100000&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let failed=if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{DocxSnapshot::from_sqlite_database(&db,&mut control).is_err()};assert!(failed);assert!(observed);}}
#[test]
fn sqlite_snapshot_docx_partial_part_reconstruction_retires_deep_completed_documents(){std::thread::Builder::new().stack_size(256*1024).spawn(||{struct Owned(Option<DocxSnapshot>);impl Drop for Owned{fn drop(&mut self){if let Some(snapshot)=self.0.take(){snapshot.retire_sqlite_snapshot();}}}let mut snapshot=fixture();let mut node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Text{text:"leaf".into()};for _ in 0..8192{node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element{name:"node".into(),attrs:Vec::new(),children:vec![node]};}snapshot.xml_parts[0].document.root=Some(node);snapshot.xml_parts[1].content_type="z".repeat(100000);let snapshot=Owned(Some(snapshot));let limits=SqliteDatabaseLimits::default();let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let mut observed=false;assert!(DocxSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::ReconstructSnapshot&&event.total==100000&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}},limits)).is_err());assert!(observed);let restored=DocxSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();restored.retire_sqlite_snapshot();}).unwrap().join().unwrap();}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_docx_actual_declaration_exposes_complete_typed_snapshot(){use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("DOCX SQLite").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.docx".into(),standard:"ecma-376".into(),subset:"*".into()};let snapshot=fixture();let file=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;let restored=io_import_sqlite_snapshot::<DocxSnapshot>(&dialect,&file,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();snapshot.retire_sqlite_snapshot();}

#[test]
fn sqlite_snapshot_docx_actual_erased_native_boundaries_retain_all_owned_fields(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.docx".into(),standard:"ecma-376".into(),subset:"*".into()};let codec=<DocxSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let payload=(codec.import)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let projected=(codec.export)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=DocxSnapshot::from_sqlite_database(&projected,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();}snapshot.retire_sqlite_snapshot();}
#[test]
fn sqlite_snapshot_docx_deep_erased_native_input_output_are_interior_cancellable(){let plan:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛫️native/🔣️.json")).unwrap();std::thread::Builder::new().stack_size(plan["smallStackBytes"].as_u64().unwrap()as usize).spawn(move||{struct Owner(Option<DocxSnapshot>);impl Drop for Owner{fn drop(&mut self){if let Some(snapshot)=self.0.take(){snapshot.retire_sqlite_snapshot();}}}let mut snapshot=fixture();let mut node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Text{text:"leaf".into()};for _ in 0..plan["depth"].as_u64().unwrap(){node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element{name:"node".into(),attrs:vec![],children:vec![node]};}snapshot.xml_parts[0].document.root=Some(node);snapshot.xml_parts[1].content_type="z".repeat(plan["lateTextBytes"].as_u64().unwrap()as usize);let snapshot=Owner(Some(snapshot));let limits=SqliteDatabaseLimits::default();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.docx".into(),standard:"ecma-376".into(),subset:"*".into()};let codec=<DocxSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let expected_database=db.clone();let payload=(codec.import)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let projected=(codec.export)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert!(projected==expected_database,"complete deep native graph differs");assert_eq!(projected.table("docx_xml_element").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="node").count(),plan["depth"].as_u64().unwrap()as usize);assert_eq!(projected.table("docx_xml_text").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="leaf").count(),1);for phase in[SqliteSnapshotPhase::EncodeNative,SqliteSnapshotPhase::DecodeNative]{let mut reached=false;let mut callback=|event:SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=plan["cancelAfter"].as_u64().unwrap()as usize&&event.completed<event.total{reached=true;false}else{true}};let failed=if phase==SqliteSnapshotPhase::EncodeNative{let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();(codec.import)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err()}else{(codec.export)(crate::STDIO_DOCX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err()};assert!(failed);assert!(reached,"actual interior native phase {phase:?}");}}}).unwrap().join().unwrap();}

#[test]
fn sqlite_snapshot_docx_native_exact_file_and_entity_admission(){
 let snapshot=fixture();let defaults=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let rows=database.tables.iter().map(|table|table.rows.len()).sum::<usize>();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let bytes=match &payload{store::io_schema::IoPayload::Binary(bytes)=>bytes.len(),store::io_schema::IoPayload::Text(text)=>text.len()};let exact=SqliteDatabaseLimits{max_file_bytes:bytes,max_rows:rows,..defaults};assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),payload);let restored=DocxSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();
 for limited in[SqliteDatabaseLimits{max_file_bytes:bytes-1,..exact},SqliteDatabaseLimits{max_rows:rows-1,..exact}]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limited)).is_err());assert!(DocxSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limited)).is_err());}
 }snapshot.retire_sqlite_snapshot();
}
